        c.pm.grants.put("com.example.cleaned|"+CAMERA,true);PermissionMaintenance.pause(c);tick(c);check(granted(c,"com.example.cleaned",CAMERA),"pause forbids subsequent commands");check(state(c).getString("status").equals("Maintien en pause"),"paused reference is distinguished from initial activation");PermissionMaintenance.resume(c);await();check(!granted(c,"com.example.cleaned",CAMERA),"resume uses existing baseline without absorbing the regrant");
