        check(diskFailure&&ControlShell.mutations==before&&c.pm.getApplicationEnabledSetting("com.example.approvaldisk")==3,"approval disk failure leaves app disabled and issues no enable");PermissionMaintenance.approve(c,"com.example.approvaldisk",stamp);
        app(c,"com.example.approvalrace",12012,CAMERA);tick(c);stamp=state(c).getJSONObject("pending").getJSONObject("com.example.approvalrace").getJSONObject("owner").getString("stamp");EventStore.pendingHook=()->c.pm.guards.put("com.example.approvalrace","Protection AIV : rôle changé");before=ControlShell.mutations;boolean roleFailure=false;try{PermissionMaintenance.approve(c,"com.example.approvalrace",stamp);}catch(IOException e){roleFailure=true;}
        check(roleFailure&&ControlShell.mutations==before&&c.pm.getApplicationEnabledSetting("com.example.approvalrace")==3&&!state(c).getJSONObject("pending").has("com.example.approvalrace"),"approval persists but a role change during receipt write prevents enabling");
        app(c,"com.example.newsystem",12001,CAMERA);c.pm.apps.get("com.example.newsystem").applicationInfo.flags|=ApplicationInfo.FLAG_SYSTEM;app(c,"com.example.newshared1",12002,CAMERA);app(c,"com.example.newshared2",12002,CAMERA);app(c,"com.example.workprofile",112003,CAMERA);tick(c);
        check(c.pm.getApplicationEnabledSetting("com.example.newsystem")==0&&c.pm.getApplicationEnabledSetting("com.example.newshared1")==0&&state(c).getInt("pending_count")==4,"system components and shared UIDs require review; another profile is excluded");
        app(c,"com.example.updatedsystem",12013,CAMERA);c.pm.apps.get("com.example.updatedsystem").applicationInfo.flags|=ApplicationInfo.FLAG_UPDATED_SYSTEM_APP;tick(c);check(c.pm.getApplicationEnabledSetting("com.example.updatedsystem")==0&&"protected_review".equals(state(c).getJSONObject("pending").getJSONObject("com.example.updatedsystem").getString("phase")),"updated system component is also exempt from automatic disable");
        c.pm.apps.get("com.example.newapp").signer="replacement-signer";c.pm.apps.get("com.example.newapp").lastUpdateTime++;tick(c);check(state(c).getJSONObject("pending").has("com.example.newapp")&&c.pm.getApplicationEnabledSetting("com.example.newapp")==3,"different signer is not accepted as a normal update");
        app(c,"com.example.refused",12004,CAMERA);ControlShell.refuse="com.example.refused";for(int i=0;i<4;i++)tick(c);check(state(c).getJSONObject("pending").getJSONObject("com.example.refused").getInt("failures")==3&&c.pm.getApplicationEnabledSetting("com.example.refused")==0,"rejected disable is reported and retries stop at three");ControlShell.refuse="";
        c.pm.flags.put("com.example.cleaned|"+BACK,"SYSTEM_FIXED");c.pm.grants.put("com.example.cleaned|"+BACK,true);before=ControlShell.mutations;for(int i=0;i<4;i++)tick(c);check(granted(c,"com.example.cleaned",BACK)&&ControlShell.mutations==before&&state(c).getInt("suspended_rights")==1,"new Android lock suspends that right without repeated Shell attempts");c.pm.flags.put("com.example.cleaned|"+BACK,"USER_SET");c.pm.grants.put("com.example.cleaned|"+BACK,false);PermissionMaintenance.prepare(c);await();check(state(c).getInt("suspended_rights")==0,"explicit addition of freshly verified denials can clear a suspension");
        app(c,"com.example.manualmore",12005,CAMERA);c.pm.grants.put("com.example.manualmore|"+CAMERA,false);PermissionMaintenance.prepare(c);await();check(!policy(c).getJSONObject("known").has("com.example.manualmore"),"adding denied states does not silently approve an unknown installed app");
        c.pm.grants.put("com.example.cleaned|"+CAMERA,true);before=ControlShell.mutations;check(ControlCoordinator.acquire(),"exclusive lease available");PermissionMaintenance.request(c);check(!PermissionMaintenance.busy()&&ControlShell.mutations==before,"maintenance never overlaps another controller");ControlCoordinator.release();
        EventStore.writable=false;tick(c);check(!state(c).getBoolean("enabled")&&granted(c,"com.example.cleaned",CAMERA)&&ControlShell.mutations==before,"unwritable audit prevents commands and suspends maintenance");EventStore.writable=true;PermissionMaintenance.resume(c);await();
        c.pm.grants.put("com.example.cleaned|"+CAMERA,true);ControlShell.failResultLog=true;tick(c);check(!state(c).getBoolean("enabled")&&!granted(c,"com.example.cleaned",CAMERA)&&PermissionMaintenance.exportState(c).getJSONObject("last_action").getString("phase").equals("confirmed"),"post-command journal failure preserves file receipt and suspends follow-up");ControlShell.failResultLog=false;EventStore.writable=true;PermissionMaintenance.resume(c);await();
