        check(!granted(c,"com.example.allowed",CAMERA)&&policy(c).getJSONObject("targets").has("com.example.allowed|"+CAMERA),"actual manual apply records its confirmed denial in existing maintenance policy");PermissionControl.restore(c);PermissionControlIntegrationTest.waitForJob();tick(c);
        check(granted(c,"com.example.allowed",CAMERA)&&!policy(c).getJSONObject("targets").has("com.example.allowed|"+CAMERA),"actual restoration durably excludes denial before granting and is not undone");
        plan=PermissionControl.preview(c,new JSONArray().put(EventStore.object("package","com.example.allowed","permissions",new JSONArray().put(CAMERA))));PermissionControl.apply(c,plan.getString("stamp"));PermissionControlIntegrationTest.waitForJob();c.pm.grants.put("com.example.allowed|"+CAMERA,true);PermissionControl.restore(c);PermissionControlIntegrationTest.waitForJob();tick(c);
        check(granted(c,"com.example.allowed",CAMERA)&&!policy(c).getJSONObject("targets").has("com.example.allowed|"+CAMERA),"explicit restore also excludes an already manually restored right");
